// ================= KONFIGURATION: hier anpassen =================
const cfg = {
  absender: 'Dekanat Fakultät 10 <dekanat@example.org>',
  unterschrift: 'Prof. Dr. Erika Beispiel, Dekanin',
  fakultaet: 'Fakultät für Informatik und Ingenieurwissenschaften (Beispiel)',
  qr_url: 'http://qr-dienst:8080',          // QR-Dienst der Sandbox
  gotenberg_url: 'http://gotenberg:3000',   // PDF-Dienst der Sandbox
};
return [{ json: { cfg } }];

// Beispieldaten, erfunden. Im Echtbetrieb: Data Table lesen oder Excel-Datei mit "Extract from File".
const frist = '30.09.2026';
const personen = [
  { anrede: 'Sehr geehrte Frau Muster', name: 'Anna Muster', email: 'anna.muster@example.org', az: 'F10-2026-0417' },
  { anrede: 'Sehr geehrter Herr Beispiel', name: 'Bernd Beispiel', email: 'bernd.beispiel@example.org', az: 'F10-2026-0418' },
  { anrede: 'Sehr geehrte Frau Probe', name: 'Carla Probe', email: 'carla.probe@example.org', az: 'F10-2026-0419' },
];
return personen.map(p => ({ json: { ...p, frist, link: 'https://example.org/rueckmeldung?az=' + p.az } }));

// Ein Brief je Person: schlichtes HTML mit Briefkopf, Anschrift, Text und dem QR-Code als eingebettetem Bild.
const cfg = $('Konfiguration').first().json.cfg;
const personen = $('Empfänger (Beispieldaten)').all();
const heute = new Date().toLocaleDateString('de-DE', { day: '2-digit', month: 'long', year: 'numeric' });
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const p = personen[i].json;
  const qr = (await this.helpers.getBinaryDataBuffer(i, 'qr')).toString('base64');
  const html = `<!doctype html><html lang="de"><head><meta charset="utf-8"><style>
    @page { size: A4; margin: 20mm 20mm 20mm 25mm; }
    body { font-family: 'Source Sans 3', 'Helvetica Neue', Arial, sans-serif; font-size: 11pt; color: #222; line-height: 1.45; }
    .kopf { border-bottom: 2px solid #C81E0F; padding-bottom: 6pt; margin-bottom: 28pt; display: flex; justify-content: space-between; }
    .kopf b { color: #C81E0F; font-size: 13pt; }
    .anschrift { margin: 0 0 28pt 0; white-space: pre-line; }
    .datum { text-align: right; margin-bottom: 18pt; }
    h1 { font-size: 13pt; margin: 0 0 12pt 0; }
    .qr { float: right; margin: 0 0 8pt 16pt; text-align: center; font-size: 8.5pt; color: #555; }
    .fuss { position: fixed; bottom: 0; left: 0; right: 0; font-size: 8.5pt; color: #777; border-top: 1px solid #ccc; padding-top: 4pt; }
  </style></head><body>
  <div class="kopf"><div><b>${esc(cfg.fakultaet)}</b><br>Dekanat</div><div>Aktenzeichen ${esc(p.az)}</div></div>
  <div class="anschrift">${esc(p.name)}
Beispielstraße 1
50678 Köln</div>
  <div class="datum">Köln, ${heute}</div>
  <div class="qr"><img src="data:image/png;base64,${qr}" width="110" height="110" alt="QR-Code"><br>Rückmeldung per QR-Code</div>
  <h1>Rückmeldung zur Prüfungsplanung, Frist ${esc(p.frist)}</h1>
  <p>${esc(p.anrede)},</p>
  <p>für die Planung des kommenden Semesters bitten wir Sie um eine kurze Rückmeldung bis zum <b>${esc(p.frist)}</b>.
  Den Zugang finden Sie über den QR-Code rechts oder unter <a href="${esc(p.link)}">${esc(p.link)}</a>.
  Die Rückmeldung dauert etwa zwei Minuten.</p>
  <p>Dieser Brief wurde automatisch erstellt und ist ohne Unterschrift gültig. Bei Fragen erreichen Sie das Dekanat
  unter dekanat@example.org.</p>
  <p>Mit freundlichen Grüßen<br><br>${esc(cfg.unterschrift)}</p>
  <div class="fuss">${esc(cfg.fakultaet)} · Beispielstraße 1 · 50678 Köln · Beispiel aus dem Vortrag, keine echte Post</div>
  </body></html>`;
  out.push({ json: { html, email: p.email, name: p.name, az: p.az,
                     betreff: `Rückmeldung zur Prüfungsplanung bis ${p.frist} (${p.az})`,
                     dateiname: 'Brief_' + p.az } });
}
return out;
